#!/usr/bin/env node
/*
 * gen-dev-docs.mjs — regenerates the AUTO-GENERATED half of the /dev-docs data.
 *
 *   1. Parses packages/database/prisma/schema.prisma  -> db-schema.generated.ts
 *   2. Scans apps/api controllers (*.controller.ts)   -> endpoints.generated.ts
 *
 * The curated half (registry.ts: APIs, features, external services) is hand
 * maintained. endpoints.generated.ts is used only for drift detection against
 * the curated API list — see apps/web/src/lib/dev-docs/index.ts.
 *
 * Run:  node scripts/gen-dev-docs.mjs   (or `pnpm gen:docs`)
 * No dependencies — plain Node fs + string parsing.
 */
import { readFileSync, writeFileSync, mkdirSync, readdirSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, relative } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SCHEMA = join(ROOT, 'packages/database/prisma/schema.prisma');
const API_SRC = join(ROOT, 'apps/api/src');
const OUT_DIR = join(ROOT, 'apps/web/src/lib/dev-docs');

const BANNER =
  '// AUTO-GENERATED by scripts/gen-dev-docs.mjs — DO NOT EDIT BY HAND.\n' +
  '// Run `pnpm gen:docs` (or `node scripts/gen-dev-docs.mjs`) to regenerate.\n\n';

// ---------------------------------------------------------------------------
// 1. Prisma schema parser
// ---------------------------------------------------------------------------
// Prisma scalar types are capitalized, so a leading-uppercase check alone would
// misread them as model references — exclude the known scalars explicitly.
const PRISMA_SCALARS = new Set([
  'String',
  'Boolean',
  'Int',
  'BigInt',
  'Float',
  'Decimal',
  'DateTime',
  'Json',
  'Bytes',
]);

// Extract a @default(...) value with balanced parens (handles cuid(), now(), etc.)
function extractDefault(attrs) {
  const i = attrs.indexOf('@default(');
  if (i < 0) return null;
  const start = i + '@default('.length;
  let depth = 0;
  let j = start;
  for (; j < attrs.length; j++) {
    const ch = attrs[j];
    if (ch === '(') depth++;
    else if (ch === ')') {
      if (depth === 0) break;
      depth--;
    }
  }
  return attrs.slice(start, j).trim() || null;
}

function parsePrisma(text) {
  const enums = [];
  const models = [];

  // enums
  const enumRe = /enum\s+(\w+)\s*\{([^}]*)\}/g;
  let m;
  while ((m = enumRe.exec(text))) {
    const values = m[2]
      .split('\n')
      .map((l) => l.replace(/\/\/.*$/, '').trim())
      .filter((l) => l && !l.startsWith('@'));
    enums.push({ name: m[1], values });
  }
  const enumNames = new Set(enums.map((e) => e.name));

  // models
  const modelRe = /model\s+(\w+)\s*\{([\s\S]*?)\n\}/g;
  while ((m = modelRe.exec(text))) {
    const name = m[1];
    const body = m[2];
    const columns = [];
    const relations = [];
    const blockAttrs = { unique: [], index: [], map: null, id: [] };

    for (const rawLine of body.split('\n')) {
      const line = rawLine.replace(/\/\/.*$/, '').trim();
      if (!line) continue;

      if (line.startsWith('@@')) {
        const u = line.match(/@@unique\(\[([^\]]+)\]\)/);
        if (u) blockAttrs.unique.push(u[1].split(',').map((s) => s.trim()));
        const i = line.match(/@@index\(\[([^\]]+)\]\)/);
        if (i) blockAttrs.index.push(i[1].split(',').map((s) => s.trim()));
        const mp = line.match(/@@map\(["']([^"']+)["']\)/);
        if (mp) blockAttrs.map = mp[1];
        const id = line.match(/@@id\(\[([^\]]+)\]\)/);
        if (id) blockAttrs.id = id[1].split(',').map((s) => s.trim());
        continue;
      }

      const parts = line.split(/\s+/);
      const fieldName = parts[0];
      const rawType = parts[1];
      if (!rawType) continue;
      const attrs = line.slice(line.indexOf(rawType) + rawType.length);

      const optional = rawType.endsWith('?');
      const list = rawType.endsWith('[]');
      const baseType = rawType.replace(/[?[\]]/g, '');

      const isModelRef =
        /^[A-Z]/.test(baseType) && !enumNames.has(baseType) && !PRISMA_SCALARS.has(baseType);
      const relMatch = attrs.match(/@relation\(([^)]*)\)/);

      if (isModelRef) {
        // navigation field (relation), not a stored column
        let fields = null;
        let references = null;
        if (relMatch) {
          const f = relMatch[1].match(/fields:\s*\[([^\]]+)\]/);
          const r = relMatch[1].match(/references:\s*\[([^\]]+)\]/);
          if (f) fields = f[1].split(',').map((s) => s.trim());
          if (r) references = r[1].split(',').map((s) => s.trim());
        }
        relations.push({
          field: fieldName,
          target: baseType,
          list,
          optional,
          fields,
          references,
          onDelete: (attrs.match(/onDelete:\s*(\w+)/) || [])[1] || null,
        });
        continue;
      }

      columns.push({
        name: fieldName,
        type: baseType + (list ? '[]' : ''),
        enum: enumNames.has(baseType) ? baseType : null,
        nullable: optional,
        isId: /@id\b/.test(attrs),
        isUnique: /@unique\b/.test(attrs),
        isForeignKey: false, // filled below
        default: extractDefault(attrs),
        updatedAt: /@updatedAt\b/.test(attrs),
      });
    }

    // mark scalar FK columns (those referenced by a relation's `fields:`)
    const fkNames = new Set(relations.flatMap((r) => r.fields || []));
    for (const c of columns) if (fkNames.has(c.name)) c.isForeignKey = true;

    models.push({ name, columns, relations, blockAttrs });
  }

  return { enums, models };
}

// ---------------------------------------------------------------------------
// 2. NestJS controller scanner (best-effort, for drift detection)
// ---------------------------------------------------------------------------
function walk(dir, out = []) {
  for (const entry of readdirSync(dir)) {
    const p = join(dir, entry);
    const st = statSync(p);
    if (st.isDirectory()) walk(p, out);
    else if (entry.endsWith('.controller.ts')) out.push(p);
  }
  return out;
}

const HTTP = ['Get', 'Post', 'Put', 'Patch', 'Delete'];

function scanController(file, text) {
  const endpoints = [];
  const prefixMatch = text.match(/@Controller\(\s*['"]?([^'")]*)['"]?\s*\)/);
  const prefix = prefixMatch ? prefixMatch[1] : '';
  // class-level guard: a @UseGuards( that appears before `export class`
  const classIdx = text.search(/export\s+class\s+\w+/);
  const classGuardMatch = text.slice(0, classIdx).match(/@UseGuards\(([^)]*)\)/);
  const classGuards = classGuardMatch ? classGuardMatch[1] : '';

  const lines = text.split('\n');
  let buf = null;
  const flush = (handler) => {
    if (buf && buf.http) {
      const route = buf.route.replace(/^['"]|['"]$/g, '');
      const full = ('/' + [prefix, route].filter(Boolean).join('/')).replace(/\/+/g, '/');
      endpoints.push({
        method: buf.http.toUpperCase(),
        path: full === '/' ? '/' : full.replace(/\/$/, ''),
        guard: (buf.guards || classGuards || '').replace(/\s+/g, ' ').trim() || 'none',
        roles: buf.roles || null,
        httpCode: buf.httpCode || null,
        handler,
        file: relative(ROOT, file).replace(/\\/g, '/'),
      });
    }
    buf = null;
  };

  for (const raw of lines) {
    const line = raw.trim();
    const httpMatch = line.match(new RegExp(`@(${HTTP.join('|')})\\(([^)]*)\\)`));
    if (httpMatch) {
      buf = buf || {};
      buf.http = httpMatch[1];
      buf.route = httpMatch[2] || '';
      continue;
    }
    if (!buf) continue;
    const g = line.match(/@UseGuards\(([^)]*)\)/);
    if (g) buf.guards = g[1];
    const r = line.match(/@Roles\(([^)]*)\)/);
    if (r) buf.roles = r[1];
    const hc = line.match(/@HttpCode\(([^)]*)\)/);
    if (hc) buf.httpCode = hc[1];
    // method signature (e.g. `async create(` or `findAll(`)
    const sig = line.match(/^(?:async\s+)?(\w+)\s*\(/);
    if (sig && !line.startsWith('@')) flush(sig[1]);
  }
  return endpoints;
}

// ---------------------------------------------------------------------------
// emit
// ---------------------------------------------------------------------------
function main() {
  mkdirSync(OUT_DIR, { recursive: true });

  const schema = parsePrisma(readFileSync(SCHEMA, 'utf8'));
  writeFileSync(
    join(OUT_DIR, 'db-schema.generated.ts'),
    BANNER +
      'export const DB_SCHEMA = ' +
      JSON.stringify(schema, null, 2) +
      ' as const;\n\nexport type DbSchema = typeof DB_SCHEMA;\n'
  );

  const files = walk(API_SRC);
  const endpoints = files.flatMap((f) => scanController(f, readFileSync(f, 'utf8')));
  endpoints.sort((a, b) => a.path.localeCompare(b.path) || a.method.localeCompare(b.method));
  writeFileSync(
    join(OUT_DIR, 'endpoints.generated.ts'),
    BANNER +
      'export const CONTROLLER_ENDPOINTS = ' +
      JSON.stringify(endpoints, null, 2) +
      ' as const;\n'
  );

  console.log(
    `gen:docs -> ${schema.models.length} models, ${schema.enums.length} enums, ${endpoints.length} endpoints`
  );
}

// Never block dev/build if generation hits a snag — the committed generated
// files remain usable. Manual runs still surface the warning.
try {
  main();
} catch (err) {
  console.warn('gen:docs skipped (kept existing generated files):', err.message);
}
